'use strict';
const local='http://127.0.0.1:17448';
const fetchJson=async(u)=>{const r=await fetch(u,{signal:AbortSignal.timeout(4000)});if(!r.ok)throw Error('http_'+r.status);return r.json()};
const exact=p=>{try{const u=new URL(p);return /(^|\.)chatgpt\.com$/.test(u.hostname)?u.pathname.replace(/\/$/,''):''}catch{return ''}};
function cdp(url,method,params={},limit=1800){
 return new Promise(resolve=>{
  let done=false,ws,open=false;const st=performance.now();
  const end=(ok,reason)=>{if(done)return;done=true;clearTimeout(t);try{ws?.close()}catch{}resolve({method,ms:Math.round(performance.now()-st),open,ok,reason})};
  const t=setTimeout(()=>end(false,'timeout'),limit);
  try{
   ws=new WebSocket(url);
   ws.addEventListener('open',()=>{open=true;try{ws.send(JSON.stringify({id:991,method,params}))}catch{end(false,'send_error')}});
   ws.addEventListener('message',e=>{try{let x=JSON.parse(e.data);if(x.id===991)end(!x.error,x.error?String(x.error.code||'CDP_ERROR'):'ok')}catch{end(false,'invalid_reply')}});
   ws.addEventListener('error',()=>end(false,'ws_error'));
  }catch{end(false,'ws_error')}
 })
}
async function main(){
 const [p,m,o]=await Promise.all([fetchJson(local+'/api/ai-profiles'),fetchJson(local+'/api/supervisor-watchdog/managed-chats?inspect=0'),fetchJson(local+'/api/operator-lifecycle')]);
 const cfg=await fetchJson(local+'/api/supervisor-watchdog?detect=0');
 if(o.queuePaused!==true||cfg.config?.mode!=='off'||cfg.config?.allowAutonomousSend!==false)throw Error('bridge_not_frozen');
 const ports=[...new Set((p.aiProfiles||[]).filter(x=>x.provider==='chatgpt'&&x.debugPort).map(x=>Number(x.debugPort)))].slice(0,8);
 const targetLists=await Promise.all(ports.map(async port=>{try{return {port,targets:await fetchJson('http://127.0.0.1:'+port+'/json/list')}}catch(e){return {port,targets:[],error:e.message}}}));
 const chats=(m.chats||[]).slice(0,8);
 const rows=[];
 for(const chat of chats){
  const t=targetLists.flatMap(x=>(x.targets||[]).filter(z=>exact(z.url)===exact(chat.url)&&z.webSocketDebuggerUrl).map(z=>({port:x.port,t:z})))[0];
  if(!t){rows.push({name:chat.name,missing:true});continue}
  const methods=['Browser.getVersion','Target.getTargetInfo','Page.getFrameTree','Runtime.evaluate'];
  const responses=[];
  for(const method of methods){
   const params=method==='Runtime.evaluate'?{expression:'2+2',awaitPromise:false,returnByValue:true}:{};
   responses.push(await cdp(t.t.webSocketDebuggerUrl,method,params,1400));
  }
  rows.push({name:chat.name,port:t.port,type:t.t.type,methods:responses});
 }
 console.log(JSON.stringify({at:new Date().toISOString(),head:'R45',ports:targetLists.map(x=>({port:x.port,targets:x.targets.length,error:x.error||''})),rows}));
}
main().catch(e=>{console.log(JSON.stringify({error:e.message}));process.exitCode=1});
